```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, s.service_name AS callee, count(*) AS n, approx_quantile(c.duration,0.5)/1e6 AS client_p50_ms, approx_quantile(s.duration,0.5)/1e6 AS server_p50_ms, approx_quantile(c.duration - s.duration,0.5)/1e6 AS gap_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.attr_span_kind='Client' AND s.attr_span_kind='Server' AND c.service_name='search' AND s.service_name='rate' GROUP BY ALL",
          "claim": "search→rate calls: client p50 about 2323 ms, but rate server p50 about 0.12 ms; the ~2322 ms gap is on the wire."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms, approx_quantile(duration,0.95)/1e6 p95_ms FROM normal_traces WHERE span_name LIKE 'rate.Rate/GetRates' GROUP BY ALL UNION ALL SELECT service_name, span_name, attr_span_kind, count(*), approx_quantile(duration,0.5)/1e6, approx_quantile(duration,0.95)/1e6 FROM abnormal_traces WHERE span_name LIKE 'rate.Rate/GetRates' GROUP BY ALL",
          "claim": "rate.Rate/GetRates client p95 rose from about 7.5 ms to about 4026 ms in search, while rate's server span stayed about 1 ms."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, s.service_name AS callee, count(*) AS n, approx_quantile(s.duration,0.95)/1e6 AS rate_server_p95_ms, approx_quantile(c.duration,0.95)/1e6 AS search_client_p95_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='search' AND s.service_name='rate' GROUP BY ALL",
          "claim": "Slow time appears in search's client calls to rate (about 4 s p95) while rate's own server handling stays about 1 ms."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, s.service_name AS callee, count(*) AS n, approx_quantile(c.duration,0.5)/1e6 AS client_p50_ms, approx_quantile(s.duration,0.5)/1e6 AS server_p50_ms, approx_quantile(c.duration - s.duration,0.5)/1e6 AS gap_p50_ms FROM abnormal_traces c JOIN abnormal_traces s ON c.trace_id=s.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='frontend' AND s.service_name='search' GROUP BY ALL",
          "claim": "frontend→search calls take about 2324 ms at p50, matching search's server time; frontend adds only about 0.3 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE span_name LIKE 'HTTP /%' AND attr_span_kind='Server' GROUP BY ALL ORDER BY p95_ms DESC",
          "claim": "Frontend HTTP /hotels p95 is about 3808 ms (normal about 13 ms); other frontend paths stay near their normal latency."
        }
      ]
    }
  ]
}
```

